def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    colors = [v for v in counts if v != background and v != 2]
    if len(colors) != 1:
        raise ValueError('expected one outline color besides background')
    outline = colors[0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == outline]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r == r0 or r == r1 or c == c0 or c == c1) and out[r][c] == background:
                out[r][c] = 2
    return out

