def transform(grid):
    """Connect aligned markers, using 2 for the cells between them."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    colors = [v for v in counts if v != background and v != 2]
    out = [row[:] for row in grid]
    for color in colors:
        # Complete only substantial aligned strokes (at least three marks);
        # isolated pairs are not joined.
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            if len(cols) >= 3:
                for c in range(min(cols), max(cols) + 1):
                    if out[r][c] == background:
                        out[r][c] = 2
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            if len(rows) >= 3:
                for r in range(min(rows), max(rows) + 1):
                    if out[r][c] == background:
                        out[r][c] = 2
    return out

