def transform(grid):
    """Connect aligned markers, using 2 for the cells between them."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    colors = [v for v in counts if v != background and v != 2]
    out = [row[:] for row in grid]
    for color in colors:
        # Bridge consecutive collinear markers across at most two empty cells.
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
