            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = next(v for v in counts if v != background and v != 2)
    bars = [r for r in range(h) if sum(v == marker for v in grid[r]) >= 4]

    # Rails require repeated marks outside the dense horizontal bars.
    rails = []
    for c in range(w):
        outside = [r for r in range(h) if grid[r][c] == marker and r not in bars]
        if len(outside) >= 2:
            rails.append(c)

    out = [row[:] for row in grid]
    if rails:
        left, right = min(rails), max(rails)
    else:
        left = min(c for r in range(h) for c in range(w) if grid[r][c] == marker)
        right = max(c for r in range(h) for c in range(w) if grid[r][c] == marker)

    # Horizontal strokes bridge their marks and meet the outer rails.
    for r in bars:
        cols = [c for c in range(w) if grid[r][c] == marker]
        lo, hi = min(min(cols), left), max(max(cols), right)
        for c in range(lo, hi + 1):
            if out[r][c] == background:
                out[r][c] = 2

    # Vertical rails bridge consecutive marks, using each crossing bar as an
    # endpoint, and thereby completing gaps between the bars and rail marks.
    for c in rails:
        rows = [r for r in range(h) if grid[r][c] == marker]
        rows += [r for r in bars if left <= c <= right]
        rows = sorted(set(rows))
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if out[r][c] == background:
                    out[r][c] = 2
    return out
