    marker = next(v for v in counts if v != background and v != 2)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)
    out = [row[:] for row in grid]

    # Bridge every horizontal gap between successive marks. Dense bars extend
    # across the full marker bounding-box width.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 4:
            lo, hi = cmin, cmax
        elif len(cols) >= 2:
            lo, hi = min(cols), max(cols)
        else:
            continue
        for c in range(lo, hi + 1):
            if out[r][c] == background:
                out[r][c] = 2

    # Fill only repeated vertical strokes (four or more original markers).
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 4:
